#include <windows.h>
#include <atomic>
#include <chrono>
#include <cstdint>
#include <cstring>
#include <iostream>
#include <string>
#include <thread>
#include <vector>

static bool isWritable(DWORD protect)
{
    DWORD p = protect & 0xFF;
    return p == PAGE_READWRITE || p == PAGE_WRITECOPY ||
           p == PAGE_EXECUTE_READWRITE || p == PAGE_EXECUTE_WRITECOPY;
}

static std::vector<uintptr_t> firstScan(HANDLE h, int32_t value)
{
    std::vector<uintptr_t> hits;
    SYSTEM_INFO si;
    GetSystemInfo(&si);
    uintptr_t addr = reinterpret_cast<uintptr_t>(si.lpMinimumApplicationAddress);
    uintptr_t end = reinterpret_cast<uintptr_t>(si.lpMaximumApplicationAddress);
    MEMORY_BASIC_INFORMATION mbi;
    std::vector<uint8_t> buf;
    while (addr < end && VirtualQueryEx(h, reinterpret_cast<LPCVOID>(addr), &mbi, sizeof mbi) == sizeof mbi) {
        uintptr_t base = reinterpret_cast<uintptr_t>(mbi.BaseAddress);
        if (mbi.State == MEM_COMMIT && !(mbi.Protect & (PAGE_GUARD | PAGE_NOACCESS)) && isWritable(mbi.Protect)) {
            buf.resize(mbi.RegionSize);
            SIZE_T got = 0;
            ReadProcessMemory(h, mbi.BaseAddress, buf.data(), mbi.RegionSize, &got);
            for (SIZE_T i = 0; i + sizeof(int32_t) <= got; i += sizeof(int32_t)) {
                int32_t v;
                std::memcpy(&v, &buf[i], sizeof v);
                if (v == value) hits.push_back(base + i);
            }
        }
        addr = base + mbi.RegionSize;
    }
    return hits;
}

static std::vector<uintptr_t> narrow(HANDLE h, const std::vector<uintptr_t>& in, int32_t value)
{
    std::vector<uintptr_t> out;
    for (uintptr_t a : in) {
        int32_t v;
        SIZE_T got = 0;
        if (ReadProcessMemory(h, reinterpret_cast<LPCVOID>(a), &v, sizeof v, &got) && got == sizeof v && v == value)
            out.push_back(a);
    }
    return out;
}

static int32_t ask(const char* prompt)
{
    std::cout << prompt;
    long long v;
    std::cin >> v;
    return static_cast<int32_t>(v);
}

int main(int argc, char** argv)
{
    DWORD pid = argc > 1 ? std::stoul(argv[1]) : static_cast<DWORD>(ask("PID: "));
    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) {
        std::cerr << "OpenProcess failed: " << GetLastError() << "\n";
        return 1;
    }

    auto hits = firstScan(h, ask("Initial value: "));
    std::cout << hits.size() << " hits\n";

    for (int pass = 1; pass <= 2 && hits.size() > 1; ++pass) {
        std::cout << "Change the value in the target, then ";
        hits = narrow(h, hits, ask("enter new value: "));
        std::cout << "Pass " << pass << ": " << hits.size() << " hits\n";
    }

    if (hits.empty()) {
        std::cout << "No candidates left.\n";
        CloseHandle(h);
        return 0;
    }

    size_t shown = hits.size() < 20 ? hits.size() : 20;
    for (size_t i = 0; i < shown; ++i)
        std::cout << "[" << i << "] 0x" << std::hex << hits[i] << std::dec << "\n";

    size_t idx = static_cast<size_t>(ask("Index to freeze: "));
    if (idx >= shown) idx = 0;
    uintptr_t target = hits[idx];
    int32_t frozen = ask("Freeze at value: ");

    std::atomic<bool> running{true};
    std::thread worker([&] {
        while (running) {
            SIZE_T wrote = 0;
            WriteProcessMemory(h, reinterpret_cast<LPVOID>(target), &frozen, sizeof frozen, &wrote);
            std::this_thread::sleep_for(std::chrono::milliseconds(50));
        }
    });

    std::cout << "Freezing 0x" << std::hex << target << std::dec << " = " << frozen << ". Press Enter to stop.\n";
    std::cin.ignore(10000, '\n');
    std::cin.get();
    running = false;
    worker.join();
    CloseHandle(h);
    return 0;
}
